/**
 * A deployed file answers the same on every self-hosting entry. The Bun entry (and `nifra dev`) serve
 * it through @nifrajs/web's `servePublicDir`; the Node entry through @nifrajs/node's own reader, so
 * pages keep the node-direct lane; the Deno entry through its own handler on Deno's file API, run here
 * on Deno itself. For one tree and one request matrix every entry, generated by the build, gives the
 * same status, type, caching, validators, length, range and body, and none reaches a file outside the
 * tree, a hidden one inside it, or the server bundle beside the client files. Each tags a file by its
 * bytes, so all three send the same tag, and a replacement that keeps a file's size and timestamps
 * still changes it.
 */
import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import { createHash } from "node:crypto"
import {
  mkdirSync,
  mkdtempSync,
  realpathSync,
  renameSync,
  rmSync,
  symlinkSync,
  utimesSync,
  writeFileSync,
} from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { server } from "@nifrajs/core"
import { type NodeServer, serve } from "@nifrajs/node"
import { servePublicDir } from "@nifrajs/web"
import { generateServerEntry } from "../../../packages/web/src/build.ts"

const PUBLIC_FILES = ["/robots.txt", "/logo.SVG", "/.well-known/acme-challenge/token"]
const HASHED_FILES = ["/assets/page-1a2b3c.js", "/assets/big-9f8e7d.bin"]
const BIG = 256 * 1024 + 7
const APP = "answered by the app"
// The page's mtime is set half a second past this, the way a copy that keeps timestamps sets it: the
// file is then sent undated, and a client holding this date cannot validate or resume it.
const MODIFIED = "Sat, 01 Jan 2022 00:00:00 GMT"
const EARLIER = "Fri, 31 Dec 2021 23:59:59 GMT"
// Times a reproducible build or a copy keeps for every file: a SOURCE_DATE_EPOCH (BuildKit's
// rewrite-timestamp, say), and the 1 s the Nix store and Jib give everything.
const KEPT_MTIMES = [Date.parse("2025-06-01T00:00:00Z") / 1000, 1]
const DENO = Bun.which("deno")
if (DENO === null && process.env.CI !== undefined) {
  throw new Error("static-files needs Deno in CI: the Deno entry is held to these answers on Deno")
}

let root = ""
let dir = ""
let node: NodeServer | undefined
let nodeBase = ""
let bunServer: ReturnType<typeof Bun.serve> | undefined
let bunBase = ""
let deno: Bun.Subprocess<"ignore", "pipe", "pipe"> | undefined
let denoBase = ""

const transpiler = new Bun.Transpiler({ loader: "ts" })
// biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: an async function's constructor is AsyncFunction, which TS does not name.
const AsyncFunction = (async () => {}).constructor as new (
  ...source: string[]
) => (...args: unknown[]) => Promise<unknown>

/** Run a generated entry's code from its static section on, with its folder at `dir`. */
function evaluateEntry(src: string, end: string, tail: string, names: string[], values: unknown[]) {
  const section = src
    .slice(src.indexOf("const STATIC_ROOT"), end === "" ? undefined : src.indexOf(end))
    .replace('new URL("./", import.meta.url)', "ROOT_URL")
    .replace('new URL("./assets/", import.meta.url)', 'new URL("./assets/", ROOT_URL)')
  return new AsyncFunction(
    "ROOT_URL",
    "fileURLToPath",
    ...names,
    `${transpiler.transformSync(section.replace("await serve(app,", "return capture("))}${tail}`,
  )(pathToFileURL(`${dir}/`), fileURLToPath, ...values)
}

function replaceOnce(text: string, from: string, to: string): string {
  if (!text.includes(from)) throw new Error(`the generated entry no longer contains: ${from}`)
  return text.replace(from, to)
}

/**
 * The generated Deno entry from its static section on, as a module for Deno itself: core's subpaths
 * from source, a stub app answering its first argument, the root at `dir`, and a loopback listener
 * on a free port.
 */
function denoModule(src: string): string {
  const core = new URL("../../../packages/core/src/", import.meta.url)
  const imports = src
    .split("\n")
    .filter(
      (line) =>
        line.startsWith("import ") && (line.includes('"@nifrajs/core/') || line.includes('"node:')),
    )
    .map((line) =>
      line.replace(/"@nifrajs\/core\/([a-z-]+)"/, (_, name: string) =>
        JSON.stringify(new URL(`${name}.ts`, core).href),
      ),
    )
  let section = src.slice(src.indexOf("const STATIC_ROOT"))
  section = replaceOnce(
    section,
    'new URL("./", import.meta.url)',
    `new URL(${JSON.stringify(pathToFileURL(`${dir}/`).href)})`,
  )
  section = replaceOnce(
    section,
    'Deno.serve({ port: Number(Deno.env.get("PORT") ?? "3000") },',
    'Deno.serve({ hostname: "127.0.0.1", port: 0, onListen: (at) => console.log("listening " + at.port) },',
  )
  return [
    ...imports,
    // The stub's answer arrives as an argument, so no value is spliced into the module's code.
    "const app = { fetch: () => new Response(Deno.args[0]) }",
    section,
  ].join("\n")
}

/** Run the Deno entry on Deno, reading only the fixture tree, and resolve once it listens. */
async function startDeno(binary: string, src: string): Promise<void> {
  const script = join(root, "deno-entry.ts")
  writeFileSync(script, denoModule(src))
  deno = Bun.spawn(
    [
      binary,
      "run",
      "--quiet",
      "--no-config",
      "--no-lock",
      `--allow-read=${root},${realpathSync(root)}`,
      "--allow-net=127.0.0.1",
      script,
      APP,
    ],
    {
      stdin: "ignore",
      stdout: "pipe",
      stderr: "pipe",
      env: { ...process.env, DENO_NO_UPDATE_CHECK: "1", NO_COLOR: "1" },
    },
  )
  const reader = deno.stdout.getReader()
  const decoder = new TextDecoder()
  let out = ""
  for (;;) {
    const port = /listening (\d+)/.exec(out)?.[1]
    if (port !== undefined) {
      reader.releaseLock()
      denoBase = `http://127.0.0.1:${port}`
      return
    }
    const chunk = await reader.read()
    if (chunk.done) {
      throw new Error(
        `the Deno entry exited before listening:\n${await new Response(deno.stderr).text()}`,
      )
    }
    out += decoder.decode(chunk.value, { stream: true })
  }
}

beforeAll(async () => {
  root = mkdtempSync(join(tmpdir(), "nifra-static-parity-"))
  dir = join(root, "deploy")
  mkdirSync(join(dir, "assets/.cache"), { recursive: true })
  mkdirSync(join(dir, ".well-known/acme-challenge"), { recursive: true })
  writeFileSync(join(dir, "server.js"), "// the server bundle")
  writeFileSync(join(dir, "robots.txt"), "User-agent: *")
  writeFileSync(join(dir, "logo.SVG"), "<svg/>")
  writeFileSync(join(dir, ".well-known/acme-challenge/token"), "token")
  writeFileSync(join(dir, "assets/page-1a2b3c.js"), "x".repeat(100))
  const modified = new Date(Date.parse(MODIFIED) + 500)
  utimesSync(join(dir, "assets/page-1a2b3c.js"), modified, modified)
  writeFileSync(join(dir, "assets/big-9f8e7d.bin"), Buffer.alloc(BIG, 1))
  // Undated: a streamed file is dated once its write settles, so parity would depend on timing.
  utimesSync(join(dir, "assets/big-9f8e7d.bin"), 0, 0)
  writeFileSync(join(dir, "assets/dated.txt"), "dated by its own write")
  writeFileSync(join(dir, "assets/manifest.json"), "{}")
  writeFileSync(join(dir, "assets/guide.pdf"), "%PDF")
  writeFileSync(join(dir, "assets/theme.css"), "body{}")
  writeFileSync(join(dir, "assets/undated.txt"), "first")
  utimesSync(join(dir, "assets/undated.txt"), 0, 0)
  symlinkSync(join(dir, "assets/theme.css"), join(dir, "assets/alias.js"))
  writeFileSync(join(dir, "assets/.cache/x.js"), "cached")
  writeFileSync(join(dir, ".env"), "SECRET=1")
  writeFileSync(join(root, "outside.txt"), "outside")
  symlinkSync(join(root, "outside.txt"), join(dir, "assets/leak.js"))
  symlinkSync(join(dir, ".env"), join(dir, "assets/env.js"))

  const entry = (target: "bun" | "node" | "deno") =>
    generateServerEntry({
      target,
      adapterImport: "../framework.ts",
      publicFiles: PUBLIC_FILES,
      hashedFiles: HASHED_FILES,
    })
  // biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: the evaluated section declares both functions it returns.
  const bun = (await evaluateEntry(
    entry("bun"),
    "const server = Bun.serve",
    "; return { staticPath, staticResponse }",
    ["servePublicDir"],
    [servePublicDir],
  )) as {
    staticPath(pathname: string): string | undefined
    staticResponse(request: Request): Promise<Response>
  }
  // The entry's own routing: a static path goes to its handler, anything else to the app.
  bunServer = Bun.serve({
    hostname: "127.0.0.1",
    port: 0,
    fetch: (request) =>
      bun.staticPath(new URL(request.url).pathname) === undefined
        ? new Response(APP)
        : bun.staticResponse(request),
  })
  bunBase = `http://127.0.0.1:${bunServer.port}`

  // biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: the evaluated section returns the options it passed to the capture stub.
  const options = (await evaluateEntry(
    entry("node"),
    "",
    "",
    ["capture"],
    [(captured: unknown) => captured],
  )) as Parameters<typeof serve>[1]
  node = await serve(
    server().get("/*", (c) => c.text(APP)),
    { ...options, hostname: "127.0.0.1", port: 0 },
  )
  nodeBase = `http://127.0.0.1:${node.port}`

  if (DENO !== null) await startDeno(DENO, entry("deno"))
  // Deno's cold start compiles the entry's TypeScript; the default hook timeout is too tight on CI.
}, 30_000)

afterAll(async () => {
  await node?.stop({ drainMs: 0 })
  await bunServer?.stop(true)
  deno?.kill()
  await deno?.exited
  rmSync(root, { recursive: true, force: true })
})

const COMPARED = [
  "content-type",
  "cache-control",
  "etag",
  "last-modified",
  "content-length",
  "content-range",
  "accept-ranges",
  "x-content-type-options",
]

interface Answer {
  readonly status: number
  readonly headers: Record<string, string | null>
  readonly body: string
}

async function read(res: Response, names = COMPARED): Promise<Answer> {
  const headers: Record<string, string | null> = {}
  for (const name of names) headers[name] = res.headers.get(name)
  return { status: res.status, headers, body: await res.text() }
}

const FUTURE = "Wed, 01 Jan 2031 00:00:00 GMT"
const PAGE = "/assets/page-1a2b3c.js"
const PAGE_TAG = `"${createHash("sha256").update("x".repeat(100)).digest("base64url").slice(0, 22)}"`
const DATED = "/assets/dated.txt"
const CASES: readonly (readonly [string, string, RequestInit?])[] = [
  ["public file", "/robots.txt"],
  ["upper-case extension", "/logo.SVG"],
  [".well-known", "/.well-known/acme-challenge/token"],
  ["hashed asset", PAGE],
  ["unhashed asset", "/assets/manifest.json"],
  ["pdf", "/assets/guide.pdf"],
  ["a link is typed by its target", "/assets/alias.js"],
  ["HEAD", PAGE, { method: "HEAD" }],
  ["range", PAGE, { headers: { range: "bytes=0-9" } }],
  ["suffix range", "/assets/big-9f8e7d.bin", { headers: { range: "bytes=-5" } }],
  ["unsatisfiable range", PAGE, { headers: { range: "bytes=500-" } }],
  ["multi-range is the whole file", PAGE, { headers: { range: "bytes=0-1,4-5" } }],
  // Every entry parses Range with @nifrajs/core/range; each case below once had a second answer.
  ["malformed range", PAGE, { headers: { range: "bytes=1-x" } }],
  ["another unit", PAGE, { headers: { range: "items=0-9" } }],
  ["inverted range", PAGE, { headers: { range: "bytes=9-0" } }],
  ["spaced, upper-case unit", PAGE, { headers: { range: "Bytes = 2-4" } }],
  ["overlapping ranges", PAGE, { headers: { range: "bytes=0-5,3-9" } }],
  ["adjacent ranges", PAGE, { headers: { range: "bytes=5-9,0-4" } }],
  [
    "one satisfiable range among unsatisfiable ones",
    PAGE,
    { headers: { range: "bytes=500-,0-1" } },
  ],
  [
    "too many ranges",
    PAGE,
    { headers: { range: `bytes=${Array.from({ length: 17 }, (_, i) => `${i}-${i}`).join(",")}` } },
  ],
  ["zero suffix", PAGE, { headers: { range: "bytes=-0" } }],
  ["suffix past the start", PAGE, { headers: { range: "bytes=-500" } }],
  ["suffix and a range", PAGE, { headers: { range: "bytes=-3,0-1" } }],
  // Validators: a range survives only an If-Range naming the file's tag; a date the file is not
  // dated by, or a stale or weak tag, sends the whole file.
  ["If-Modified-Since before the file", PAGE, { headers: { "if-modified-since": EARLIER } }],
  ["If-Modified-Since at its kept mtime", PAGE, { headers: { "if-modified-since": MODIFIED } }],
  ["malformed If-Modified-Since", PAGE, { headers: { "if-modified-since": "yesterday" } }],
  ["If-Range the file's tag", PAGE, { headers: { range: "bytes=0-9", "if-range": PAGE_TAG } }],
  ["If-Range a weak tag", PAGE, { headers: { range: "bytes=0-9", "if-range": `W/${PAGE_TAG}` } }],
  ["If-Range at its kept mtime", PAGE, { headers: { range: "bytes=0-9", "if-range": MODIFIED } }],
  ["If-Range before the file", PAGE, { headers: { range: "bytes=0-9", "if-range": EARLIER } }],
  ["If-Range after the file", PAGE, { headers: { range: "bytes=0-9", "if-range": FUTURE } }],
  ["If-Range a stale tag", PAGE, { headers: { range: "bytes=0-9", "if-range": '"0-64"' } }],
  ["If-Range without Range", PAGE, { headers: { "if-range": EARLIER } }],
  ["a file its own write dated", DATED],
]

/** Requests a current cached copy answers with a header-only 304. */
const NOT_MODIFIED: readonly (readonly [string, RequestInit])[] = [
  ["If-None-Match the file's tag", { headers: { "if-none-match": PAGE_TAG } }],
  ["a weak If-None-Match", { headers: { "if-none-match": `W/${PAGE_TAG}` } }],
  ["one tag of several", { headers: { "if-none-match": `"stale", ${PAGE_TAG}` } }],
  ["HEAD", { method: "HEAD", headers: { "if-none-match": PAGE_TAG } }],
  // Conditionals are evaluated before Range (RFC 9110 section 13.2.2).
  ["with a Range", { headers: { "if-none-match": PAGE_TAG, range: "bytes=0-9" } }],
]
// What a cache refreshes its stored copy from (RFC 9111 section 4.3.4). Node's 304 leaves out
// nosniff and accept-ranges, which the cache keeps from the stored 200.
const REVALIDATED = ["content-type", "content-length", "cache-control", "etag", "last-modified"]

const REFUSED = ["/assets/leak.js", "/assets/env.js", "/assets/.cache/x.js", "/assets/missing.js"]
const TO_THE_APP = ["/server.js", "/.env", "/about"]

for (const [runtime, base] of [
  ["Bun", () => bunBase],
  ["Node", () => nodeBase],
  ["Deno", () => denoBase],
] as const) {
  describe.skipIf(runtime === "Deno" && DENO === null)(`${runtime} static cache validators`, () => {
    test("streamed files carry no content tag and refuse guarded ranges", async () => {
      const url = `${base()}/assets/big-9f8e7d.bin`
      for (const method of ["GET", "HEAD"]) {
        const response = await fetch(url, { method })
        expect(response.status).toBe(200)
        expect(response.headers.get("etag")).toBeNull()
        expect(response.headers.get("last-modified")).toBeNull()
        expect((await response.arrayBuffer()).byteLength).toBe(method === "HEAD" ? 0 : BIG)
      }
      for (const validator of ['"stale"', FUTURE]) {
        const response = await fetch(url, {
          headers: { range: "bytes=0-9", "if-range": validator },
        })
        expect(response.status).toBe(200)
        expect((await response.arrayBuffer()).byteLength).toBe(BIG)
      }
      const range = await fetch(url, { headers: { range: "bytes=0-9" } })
      expect(range.status).toBe(206)
      expect((await range.arrayBuffer()).byteLength).toBe(10)
    })

    test("a nonmatching tag suppresses the date condition, for GET and HEAD", async () => {
      for (const method of ["GET", "HEAD"]) {
        const response = await fetch(base() + PAGE, {
          method,
          headers: { "if-none-match": '"stale"', "if-modified-since": FUTURE },
        })
        expect(response.status).toBe(200)
        expect(await response.text()).toBe(method === "HEAD" ? "" : "x".repeat(100))
      }
    })

    test("the wildcard matches an existing file before date and range conditions", async () => {
      const response = await fetch(base() + PAGE, {
        headers: { "if-none-match": "*", "if-modified-since": EARLIER, range: "bytes=500-" },
      })
      expect(response.status).toBe(304)
      expect(await response.text()).toBe("")
    })

    test("a zero timestamp cannot validate a replaced file or a resumed download", async () => {
      const file = join(dir, "assets/undated.txt")
      const url = `${base()}/assets/undated.txt`
      writeFileSync(file, "first")
      utimesSync(file, 0, 0)
      const first = await fetch(url)
      const etag = first.headers.get("etag") ?? ""
      expect(etag).toMatch(/^"[\w-]{22}"$/)
      expect(first.headers.get("last-modified")).toBeNull()
      expect(await first.text()).toBe("first")
      writeFileSync(file, "other")
      utimesSync(file, 0, 0)
      const conditions: Record<string, string>[] = [
        { "if-none-match": etag },
        { "if-modified-since": new Date(0).toUTCString() },
        { range: "bytes=1-3", "if-range": new Date(0).toUTCString() },
        { range: "bytes=1-3", "if-range": etag },
      ]
      for (const headers of conditions) {
        const response = await fetch(url, { headers })
        expect(response.status).toBe(200)
        expect(await response.text()).toBe("other")
      }
      const wildcard = await fetch(url, { headers: { "if-none-match": "*" } })
      expect(wildcard.status).toBe(304)
      expect(await wildcard.text()).toBe("")
    })

    test("a same-size replacement that keeps its mtime is neither validated nor spliced", async () => {
      const name = `assets/kept-${runtime.toLowerCase()}.txt`
      const file = join(dir, name)
      const staged = join(dir, `assets/.kept-${runtime.toLowerCase()}`)
      const answers: string[] = []
      for (const mtime of KEPT_MTIMES) {
        for (const replace of ["in place", "renamed over"]) {
          writeFileSync(file, "first version")
          utimesSync(file, mtime, mtime)
          const first = await fetch(`${base()}/${name}`)
          expect(await first.text()).toBe("first version")
          if (replace === "in place") {
            writeFileSync(file, "other version")
            utimesSync(file, mtime, mtime)
          } else {
            writeFileSync(staged, "other version")
            utimesSync(staged, mtime, mtime)
            renameSync(staged, file)
          }
          // What a client holding the first version sends: its tag, or the date it was served with
          // (the kept mtime itself where none was sent).
          const etag = first.headers.get("etag") ?? '"none"'
          const date = first.headers.get("last-modified") ?? new Date(mtime * 1000).toUTCString()
          const conditions: [string, Record<string, string>][] = [
            ["If-None-Match", { "if-none-match": etag }],
            ["If-Modified-Since", { "if-modified-since": date }],
            ["If-Range tag", { range: "bytes=0-4", "if-range": etag }],
            ["If-Range date", { range: "bytes=0-4", "if-range": date }],
          ]
          for (const [condition, headers] of conditions) {
            const response = await fetch(`${base()}/${name}`, { headers })
            const body = await response.text()
            if (response.status !== 200 || body !== "other version") {
              answers.push(`mtime ${mtime}, ${replace}, ${condition}: ${response.status} ${body}`)
            }
            if (condition === "If-None-Match") {
              const current = response.headers.get("etag") ?? ""
              const revalidated = await fetch(`${base()}/${name}`, {
                headers: { "if-none-match": current },
              })
              await revalidated.arrayBuffer()
              if (current === etag || revalidated.status !== 304) {
                answers.push(
                  `mtime ${mtime}, ${replace}: tag ${current} gave ${revalidated.status}`,
                )
              }
            }
          }
        }
      }
      expect(answers).toEqual([])
    })

    test("a file its own write dated revalidates by that date, and resumes only by its tag", async () => {
      const first = await fetch(base() + DATED)
      const date = first.headers.get("last-modified") ?? ""
      const etag = first.headers.get("etag") ?? ""
      expect(await first.text()).toBe("dated by its own write")
      expect(Date.parse(date)).toBeGreaterThan(Date.now() - 600_000)
      const before = new Date(Date.parse(date) - 1000).toUTCString()
      const answers: (readonly [Record<string, string>, number, string])[] = []
      for (const headers of [
        { "if-modified-since": date },
        { "if-modified-since": FUTURE },
        { "if-modified-since": before },
        { range: "bytes=0-4", "if-range": etag },
        { range: "bytes=0-4", "if-range": date },
      ]) {
        const response = await fetch(base() + DATED, { headers })
        answers.push([headers, response.status, await response.text()])
      }
      const whole = "dated by its own write"
      expect(answers).toEqual([
        [{ "if-modified-since": date }, 304, ""],
        [{ "if-modified-since": FUTURE }, 304, ""],
        [{ "if-modified-since": before }, 200, whole],
        [{ range: "bytes=0-4", "if-range": etag }, 206, "dated"],
        // The file has a strong tag, so a date cannot stand in for it.
        [{ range: "bytes=0-4", "if-range": date }, 200, whole],
      ])
    })
  })
}

describe("static-file parity: Bun entry (servePublicDir) and Node entry (@nifrajs/node reader)", () => {
  for (const [name, path, init] of CASES) {
    test(name, async () => {
      const bun = await read(await fetch(bunBase + path, init))
      const nodeAnswer = await read(await fetch(nodeBase + path, init))
      // Answered from disk, not refused: the refusals have their own test below.
      expect(bun.status).not.toBe(404)
      expect(nodeAnswer).toEqual(bun)
    })
  }

  test("a file the Node entry streams declares its length on both, whole and ranged", async () => {
    for (const [init, status, length] of [
      [undefined, 200, BIG],
      [{ headers: { range: `bytes=1-${BIG - 2}` } }, 206, BIG - 2],
    ] as const) {
      const bun = await read(await fetch(`${bunBase}/assets/big-9f8e7d.bin`, init))
      const nodeAnswer = await read(await fetch(`${nodeBase}/assets/big-9f8e7d.bin`, init))
      expect([bun.status, bun.headers["content-length"]]).toEqual([status, String(length)])
      expect(nodeAnswer).toEqual(bun)
    }
  })

  for (const [name, init] of NOT_MODIFIED) {
    test(`a current cached copy is a 304: ${name}`, async () => {
      const bun = await read(await fetch(bunBase + PAGE, init), REVALIDATED)
      const nodeAnswer = await read(await fetch(nodeBase + PAGE, init), REVALIDATED)
      expect(bun.status).toBe(304)
      expect(bun.headers.etag).toBe(PAGE_TAG)
      expect(nodeAnswer).toEqual(bun)
    })
  }

  test("nothing outside the tree, hidden inside it, or missing is served", async () => {
    for (const path of REFUSED) {
      const bun = await fetch(bunBase + path)
      const nodeAnswer = await fetch(nodeBase + path)
      expect([path, bun.status, nodeAnswer.status]).toEqual([path, 404, 404])
      for (const body of [await bun.text(), await nodeAnswer.text()]) {
        expect(body).not.toContain("outside")
        expect(body).not.toContain("SECRET")
      }
    }
  })

  test("the server bundle and unlisted root files reach the app, never the disk", async () => {
    for (const path of TO_THE_APP) {
      expect(await (await fetch(bunBase + path)).text()).toBe(APP)
      expect(await (await fetch(nodeBase + path)).text()).toBe(APP)
    }
  })
})

// Skipped only off CI: CI without Deno fails at the top of this file.
describe.skipIf(DENO === null)(
  "static-file parity: Deno entry, on Deno, answers as the Bun entry",
  () => {
    for (const [name, path, init] of CASES) {
      test(name, async () => {
        const bun = await read(await fetch(bunBase + path, init))
        expect(await read(await fetch(denoBase + path, init))).toEqual(bun)
      })
    }

    test("a file above the buffered size: the same bytes, and Deno declares its length", async () => {
      const bun = await fetch(`${bunBase}/assets/big-9f8e7d.bin`)
      const denoAnswer = await fetch(`${denoBase}/assets/big-9f8e7d.bin`)
      expect(denoAnswer.headers.get("content-type")).toBe(bun.headers.get("content-type"))
      expect(denoAnswer.headers.get("last-modified")).toBe(bun.headers.get("last-modified"))
      expect(denoAnswer.headers.get("etag")).toBe(bun.headers.get("etag"))
      expect(denoAnswer.headers.get("content-length")).toBe(String(BIG))
      expect(Buffer.from(await denoAnswer.arrayBuffer())).toEqual(
        Buffer.from(await bun.arrayBuffer()),
      )
    })

    for (const [name, init] of NOT_MODIFIED) {
      test(`a current cached copy is a 304: ${name}`, async () => {
        const bun = await read(await fetch(bunBase + PAGE, init))
        expect(bun.status).toBe(304)
        expect(await read(await fetch(denoBase + PAGE, init))).toEqual(bun)
      })
    }

    test("nothing outside the tree, hidden inside it, or missing is served", async () => {
      for (const path of REFUSED) {
        const answer = await fetch(denoBase + path)
        const body = await answer.text()
        expect([path, answer.status]).toEqual([path, 404])
        expect(body).not.toContain("outside")
        expect(body).not.toContain("SECRET")
      }
    })

    test("the server bundle and unlisted root files reach the app, never the disk", async () => {
      for (const path of TO_THE_APP) expect(await (await fetch(denoBase + path)).text()).toBe(APP)
    })
  },
)
